        private Label NewLabel(string text, int x, int y, int w, int h, float size, FontStyle style, Color color)
        {
            Label l = new Label();
            l.Text = text;
            l.Bounds = new Rectangle(x, y, w, h);
            l.Font = new Font(UiMetrics.FontFamily, size, style);
            l.ForeColor = color;
            l.BackColor = Color.Transparent;
            l.AutoEllipsis = true;
            return l;
        }

        private UsageRow NewRow(string caption, int x, int y, int w)
        {
            UsageRow r = new UsageRow();
            r.Caption = caption;
            r.Bounds = new Rectangle(x, y, w, UiMetrics.UsageRowHeight);
            return r;
        }

        private Label NewValueLabel(int x, int y, int w)
        {
            Label l = NewLabel("—", x, y, w, UiMetrics.EquationLabelHeight,
                UiMetrics.FontValue, FontStyle.Bold, Palette.Text);
            l.BackColor = Palette.Card;
            l.TextAlign = ContentAlignment.MiddleCenter;
            l.Cursor = Cursors.IBeam;
            l.AutoEllipsis = true;
            return l;
        }

        // ---------- 布局 / 显示 ----------
        private void LayoutContent()
        {
            if (dsCard == null || goCard == null || refreshBar == null) return;
            int w = ClientSize.Width;
            dsCard.Width = w - UiMetrics.CardWidthInset;
            goCard.Width = w - UiMetrics.CardWidthInset;
            refreshBar.Width = w - UiMetrics.RefreshBarWidthInset;
            if (equationPanel != null) equationPanel.Width = dsCard.Width;
            if (dsBar != null)
            {
                dsBar.Left = UiMetrics.DeepSeekBarLeft;
                dsBar.Width = dsCard.Width - UiMetrics.DeepSeekBarWidthInset;
            }
            if (deepSeekStatus != null) deepSeekStatus.Width = dsCard.Width - UiMetrics.CardContentInset;
            if (deepSeekBalanceOnly != null) deepSeekBalanceOnly.Width = dsCard.Width - UiMetrics.CardContentInset;
            if (deepSeekPeriod != null) deepSeekPeriod.Left = dsCard.Width - UiMetrics.DeepSeekPeriodRightInset;
            if (dsRefreshButton != null)
                dsRefreshButton.Left = dsCard.Width - UiMetrics.TitleButtonRightInset -
                    UiMetrics.TitleButtonSize;
            if (goRefreshButton != null)
                goRefreshButton.Left = goCard.Width - UiMetrics.TitleButtonRightInset -
                    UiMetrics.TitleButtonSize;
            if (row5h != null && rowWeek != null && rowMonth != null)
            {
                int rowWidth = goCard.Width - UiMetrics.CardContentInset;
                row5h.Width = rowWidth;
                rowWeek.Width = rowWidth;
                rowMonth.Width = rowWidth;
            }
            LayoutEquation();
        }

        private static int MeasureEquationWidth(Label label)
        {
            string text = string.IsNullOrEmpty(label.Text) ? "0" : label.Text;
            Size size = TextRenderer.MeasureText(text, label.Font,
                new Size(int.MaxValue, label.Height),
                TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);
            return size.Width + UiMetrics.EquationMeasurePadding;
        }

        private static int MeasureEquationSymbolWidth(Label label)
        {
            Size size = TextRenderer.MeasureText(label.Text, label.Font,
                new Size(int.MaxValue, label.Height),
                TextFormatFlags.NoPadding | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix);
            return Math.Max(UiMetrics.EquationSymbolInitialWidth,
                size.Width + UiMetrics.EquationSymbolPadding);
        }

        private static void PlaceEquation(Label label, int x, int width)
        {
            if (width < UiMetrics.EquationMinLabelWidth) width = UiMetrics.EquationMinLabelWidth;
            label.Bounds = new Rectangle(x, 0, width, UiMetrics.EquationLabelHeight);
        }

        private void LayoutEquation()
        {
            if (equationPanel == null || deepSeekBalance == null || spentLabel == null ||
                totalLabel == null || plusLabel == null || equalsLabel == null) return;

            int available = equationPanel.Width - UiMetrics.EquationAvailableInset;
            if (available < UiMetrics.EquationMinAvailableWidth) return;
            int gap = UiMetrics.EquationGap;
            int plusWidth = MeasureEquationSymbolWidth(plusLabel);
            int equalsWidth = MeasureEquationSymbolWidth(equalsLabel);
            int symbolsWidth = plusWidth + equalsWidth;

            int balanceWidth = MeasureEquationWidth(deepSeekBalance);
            int spentWidth = MeasureEquationWidth(spentLabel);
            int totalWidth = MeasureEquationWidth(totalLabel);
            int needed = balanceWidth + spentWidth + totalWidth + symbolsWidth + gap * UiMetrics.EquationGapCount;
            int left = UiMetrics.EquationHorizontalMargin;

            if (needed > available)
            {
                int values = Math.Max(UiMetrics.EquationMinValuesAreaWidth,
                    available - symbolsWidth - gap * UiMetrics.EquationGapCount);
                int sum = Math.Max(1, balanceWidth + spentWidth + totalWidth);
                balanceWidth = Math.Max(UiMetrics.EquationMinValueWidth,
                    (int)Math.Round((double)values * balanceWidth / sum));
                spentWidth = Math.Max(UiMetrics.EquationMinValueWidth,
                    (int)Math.Round((double)values * spentWidth / sum));
                totalWidth = Math.Max(UiMetrics.EquationMinValueWidth, values - balanceWidth - spentWidth);
                if (balanceWidth + spentWidth + totalWidth > values)
                {
                    int over = balanceWidth + spentWidth + totalWidth - values;
                    balanceWidth = Math.Max(UiMetrics.EquationMinValueWidth, balanceWidth - over);
                    over = balanceWidth + spentWidth + totalWidth - values;
                    if (over > 0) spentWidth = Math.Max(UiMetrics.EquationMinValueWidth, spentWidth - over);
                }
            }
            else
            {
                left += (available - needed) / 2;
            }

            int x = left;
            PlaceEquation(deepSeekBalance, x, balanceWidth);
            x += balanceWidth + gap;
            PlaceEquation(plusLabel, x, plusWidth);
            x += plusWidth + gap;
            PlaceEquation(spentLabel, x, spentWidth);
            x += spentWidth + gap;
            PlaceEquation(equalsLabel, x, equalsWidth);
            x += equalsWidth + gap;
            PlaceEquation(totalLabel, x, totalWidth);
        }

        private Rectangle ValueRect(Label l)
        {
            return new Rectangle(
                dsCard.Left + equationPanel.Left + l.Left,
                dsCard.Top + equationPanel.Top + l.Top,
                l.Width,
                l.Height);
        }

        private void UpdateProviderLayout()
        {
            if (dsCard == null || goCard == null || refreshBar == null) return;
            bool ds = cfg.ShowDeepSeek;
            bool go = cfg.ShowOpenCode;
            dsCard.Visible = ds;
            goCard.Visible = go;

            const int pad = UiMetrics.OuterMargin;
            const int barGap = UiMetrics.RefreshBarGap;
            int w = ClientSize.Width;
            int top = pad;

            if (ds)
            {
                dsCard.Bounds = new Rectangle(pad, top, w - UiMetrics.CardWidthInset,
                    UiMetrics.DeepSeekCardHeight);
                top += UiMetrics.DeepSeekCardHeight;
            }

            if (ds && go)
            {
                refreshBar.Bounds = new Rectangle(UiMetrics.RefreshBarInset, top + barGap,
                    w - UiMetrics.RefreshBarWidthInset, UiMetrics.RefreshBarHeight);
                top = refreshBar.Bottom + barGap;
            }

            if (go)
            {
                goCard.Bounds = new Rectangle(pad, top, w - UiMetrics.CardWidthInset,
                    UiMetrics.OpenCodeCardHeight);
                top += UiMetrics.OpenCodeCardHeight;
            }

            bool barAtEnd = !ds || !go;
            if (barAtEnd)
            {
                // At the top or bottom, use the same compact 5px padding on both sides.
                refreshBar.Bounds = new Rectangle(UiMetrics.RefreshBarInset,
                    (ds || go) ? top + barGap : barGap, w - UiMetrics.RefreshBarWidthInset,
                    UiMetrics.RefreshBarHeight);
                top = refreshBar.Bottom;
            }

            refreshBar.Visible = true;
            int height = top + (barAtEnd ? barGap : pad);
            if (ClientSize.Height != height)
            {
                ClientSize = new Size(ClientSize.Width, height);
                if (IsHandleCreated)
                {
                    Rectangle wa = Screen.FromControl(this).WorkingArea;
                    if (Bottom > wa.Bottom) Top = Math.Max(wa.Top, wa.Bottom - Height);
                }
            }

            LayoutContent();
            Invalidate(true);
        }
    }
}

// ---- source: MainForm.Data.cs ----
namespace QuotaFloat
{
    using System;
    using System.Collections.Generic;
    using System.Diagnostics;
    using System.Drawing;
    using System.Drawing.Drawing2D;
    using System.Globalization;
    using System.IO;
    using System.Net;
    using System.Runtime.InteropServices;
    using System.Security.Cryptography;
    using System.Text;
    using System.Threading.Tasks;
    using System.Web.Script.Serialization;
    using System.Windows.Forms;
    using Microsoft.Win32;
    internal sealed partial class MainForm
    {
        // ---------- 数据获取 ----------
        private int CurrentRefreshSeconds()
        {
            return edgeHidden ? Timing.HiddenRefreshSeconds : Timing.VisibleRefreshSeconds;
        }

        private double SecondsSince(long stamp)
        {
            if (stamp == Timing.NoStamp) return double.MaxValue;
            return ElapsedSeconds(stamp);
        }

        private double ElapsedSeconds(long stamp)
        {
            if (stamp == Timing.NoStamp) return 0.0;
            return (clock.ElapsedTicks - stamp) / (double)Stopwatch.Frequency;
        }

        private double ElapsedMilliseconds(long stamp)
        {
            return ElapsedSeconds(stamp) * Timing.MillisecondsPerSecond;
        }

        private double OldestFetchAgeSeconds()
        {
            double age = -1.0;
            if (lastDeepSeekFetchStamp != Timing.NoStamp)
                age = SecondsSince(lastDeepSeekFetchStamp);
            if (lastOpenCodeFetchStamp != Timing.NoStamp)
            {
                double goAge = SecondsSince(lastOpenCodeFetchStamp);
                if (age < 0.0 || goAge > age) age = goAge;
            }
            return age;
        }

        private float NextRefreshFraction()
        {
            float fraction = 1f;
            bool any = false;
            if (cfg.DeepSeekKey.Length > 0)
            {
                fraction = Math.Min(fraction, RemainingFraction(lastDeepSeekFetchStamp,
                    EffectiveFetchSeconds(deepSeekFailureCount)));
                any = true;
            }
            if (cfg.OpenCodeKey.Length > 0)
            {
                fraction = Math.Min(fraction, RemainingFraction(lastOpenCodeFetchStamp,
                    EffectiveFetchSeconds(openCodeFailureCount)));
                any = true;
            }
            return any ? fraction : 1f;
        }

        private float RemainingFraction(long stamp, int interval)
        {
            if (stamp == Timing.NoStamp) return 0f;
            double remaining = 1.0 - SecondsSince(stamp) / interval;
            return (float)Math.Max(0.0, Math.Min(1.0, remaining));
        }

        private int EffectiveFetchSeconds(int failureCount)
        {
            int normal = CurrentRefreshSeconds();
            if (failureCount <= 0) return normal;
            int shift = Math.Min(failureCount - 1, Timing.RetryShiftLimit);
            int retry = Timing.RetryBaseSeconds << shift;
            return Math.Min(normal, Math.Max(Timing.RetryBaseSeconds, retry));
        }

        private static long ToUtcTicks(DateTimeOffset? value)
        {
            return value.HasValue ? value.Value.UtcDateTime.Ticks : 0;
        }

        private static DateTimeOffset? FromUtcTicks(long ticks)
        {
            if (ticks <= 0) return null;
            return new DateTimeOffset(new DateTime(ticks, DateTimeKind.Utc));
        }

        private static DateTime? LocalTimeFromUtcTicks(long ticks)
        {
            if (ticks <= 0) return null;
            return new DateTime(ticks, DateTimeKind.Utc).ToLocalTime();
        }

        private void StartDueFetches()
        {
            if (cfg.DeepSeekKey.Length > 0 && !fetchingDeepSeek &&
                SecondsSince(lastDeepSeekFetchStamp) >= EffectiveFetchSeconds(deepSeekFailureCount))
                StartDeepSeekFetch();
            if (cfg.OpenCodeKey.Length > 0 && !fetchingOpenCode &&
                SecondsSince(lastOpenCodeFetchStamp) >= EffectiveFetchSeconds(openCodeFailureCount))
                StartOpenCodeFetch();
        }

        private void RefreshIfStaleOnReveal()
        {
            if (demoMode || refreshingPaused) return;
            int dsAge = Math.Min(Timing.RevealRefreshMinAgeSeconds,
                EffectiveFetchSeconds(deepSeekFailureCount));
            int goAge = Math.Min(Timing.RevealRefreshMinAgeSeconds,
                EffectiveFetchSeconds(openCodeFailureCount));
            if (cfg.DeepSeekKey.Length > 0 && !fetchingDeepSeek &&
                SecondsSince(lastDeepSeekFetchStamp) >= dsAge)
                StartDeepSeekFetch();
            if (cfg.OpenCodeKey.Length > 0 && !fetchingOpenCode &&
                SecondsSince(lastOpenCodeFetchStamp) >= goAge)
                StartOpenCodeFetch();
        }

        private void StartFetch()
        {
            StartDeepSeekFetch();
            StartOpenCodeFetch();
        }

        private void StartDeepSeekFetch()
        {
            if (fetchingDeepSeek) return;
            int version = ++deepSeekRequestVersion;
            fetchingDeepSeek = true;
            dsRefreshButton.SetBusy(true, clock.ElapsedMilliseconds);
            UpdateFetchUi();

            string key = cfg.DeepSeekKey;
            if (string.IsNullOrEmpty(key))
            {
                ApplyDeepSeek(new DeepSeekState());
                return;
            }

            Task<DeepSeekState>.Factory.StartNew(delegate
            {
                return FetchDeepSeek(key);
            }).ContinueWith(delegate(Task<DeepSeekState> t)
            {
                try
                {
                    if (IsDisposed || !IsHandleCreated) return;
                    BeginInvoke(new Action(delegate
                    {
                        if (version != deepSeekRequestVersion) return;
                        DeepSeekState state;
                        if (t.IsFaulted || t.IsCanceled)
                            state = new DeepSeekState
                            {
                                Configured = key.Length > 0,
                                Error = Strings.QueryFailed
                            };
                        else
                            state = t.Result;
                        ApplyDeepSeek(state);
                    }));
                }
                catch { }
            });
        }

        private void StartOpenCodeFetch()
        {
            if (fetchingOpenCode) return;
            int version = ++openCodeRequestVersion;
            fetchingOpenCode = true;
            goRefreshButton.SetBusy(true, clock.ElapsedMilliseconds);
            UpdateFetchUi();

            string key = cfg.OpenCodeKey;
            if (string.IsNullOrEmpty(key))
            {
                ApplyOpenCode(new GoState());
                return;
            }

            Task<GoState>.Factory.StartNew(delegate
            {
                return FetchGo(key);
            }).ContinueWith(delegate(Task<GoState> t)
            {
                try
                {
                    if (IsDisposed || !IsHandleCreated) return;
                    BeginInvoke(new Action(delegate
                    {
                        if (version != openCodeRequestVersion) return;
                        GoState state;
                        if (t.IsFaulted || t.IsCanceled)
                            state = new GoState
                            {
                                Configured = key.Length > 0,
                                Error = Strings.QueryFailed
                            };
                        else
                            state = t.Result;
                        ApplyOpenCode(state);
                    }));
                }
                catch { }
            });
        }

        private void InvalidateDeepSeekFetch()
        {
            deepSeekRequestVersion++;
            deepSeekFailureCount = 0;
            fetchingDeepSeek = false;
            dsRefreshButton.SetBusy(false, clock.ElapsedMilliseconds);
            UpdateFetchUi();
            UpdateFetchTooltips();
        }

        private void InvalidateOpenCodeFetch()
        {
            openCodeRequestVersion++;
            openCodeFailureCount = 0;
            fetchingOpenCode = false;
            goRefreshButton.SetBusy(false, clock.ElapsedMilliseconds);
            UpdateFetchUi();
            UpdateFetchTooltips();
        }

        private void UpdateFetchUi()
        {
            bool any = AnyFetching;
            refreshBar.Indeterminate = any;
            if (any)
            {
                refreshBar.Phase = (float)((clock.ElapsedMilliseconds %
                    Timing.ShimmerPeriodMilliseconds) / (double)Timing.ShimmerPeriodMilliseconds);
            }
            refreshBar.Invalidate();
        }

        private void UpdateFetchTooltips()
        {
            tips.SetToolTip(dsRefreshButton,
                FetchTooltip(Strings.RefreshDeepSeekTip, deepSeekLastSuccess, deepSeekFailureCount));
            tips.SetToolTip(goRefreshButton,
                FetchTooltip(Strings.RefreshOpenCodeTip, openCodeLastSuccess, openCodeFailureCount));
        }

        private static string FetchTooltip(string baseText, DateTime? lastSuccess, int failures)
        {
            string text = baseText + Environment.NewLine + Strings.LastSuccess(lastSuccess);
            if (failures > 0)
                text += Environment.NewLine + Strings.ConsecutiveFailures(failures);
            return text;
        }

        private void ApplyDeepSeek(DeepSeekState ds)
        {
            if (IsDisposed) return;
            fetchingDeepSeek = false;
            lastDeepSeekFetchStamp = clock.ElapsedTicks;
            dsRefreshButton.SetBusy(false, clock.ElapsedMilliseconds);
            UpdateFetchUi();
            if (!ds.Configured)
                deepSeekFailureCount = 0;
            else if (!ds.Ok)
                deepSeekFailureCount++;
            else
            {
                deepSeekFailureCount = 0;
                deepSeekLastSuccess = DateTime.Now;
                cfg.DeepSeekCacheUtcTicks = DateTime.UtcNow.Ticks;
            }

            if (!ds.Configured)
            {
                if (editingField != UiMetrics.EquationFieldNone) EndEdit(false);
                lastDeepSeekBalanceKnown = false;
                deepSeekStatus.Text = Strings.NotConfiguredHint;
                deepSeekStatus.ForeColor = Palette.Sub;
                UpdateDisplay();
            }
            else if (!ds.Ok)
            {
                if (editingField != UiMetrics.EquationFieldNone) EndEdit(false);
                lastDeepSeekBalanceKnown = false;
                deepSeekStatus.Text = ds.Error;
                deepSeekStatus.ForeColor = Palette.Red;
                UpdateDisplay();
            }
            else
            {
                lastDeepSeekBalance = ds.Total;
                lastDeepSeekCurrency = ds.Currency;
                lastDeepSeekBalanceKnown = true;

                cfg.DeepSeekBalance = ds.Total;
                cfg.DeepSeekCurrency = ds.Currency;
                cfg.DeepSeekBalanceKnown = true;
                cfg.DeepSeekSpent = cfg.DeepSeekHasTotal
                    ? Math.Max(0m, cfg.DeepSeekTotal - ds.Total)
                    : 0m;
                cfg.Save();

                if (editingField != UiMetrics.EquationFieldNone && cfg.EquationEnabled)
                {
                    string sym = CurrencySymbol(ds.Currency);
                    deepSeekBalance.Text = sym + " " + ds.Total.ToString("0.00", CultureInfo.InvariantCulture);
                }
                else
                {
                    UpdateDisplay();
                }
            }

            UpdateFetchTooltips();
            if (edgeHidden || hintAlpha > 0f) Invalidate();
        }

        private void ApplyOpenCode(GoState go)
        {
            if (IsDisposed) return;
            fetchingOpenCode = false;
            lastOpenCodeFetchStamp = clock.ElapsedTicks;
            goRefreshButton.SetBusy(false, clock.ElapsedMilliseconds);
            UpdateFetchUi();

            if (!go.Configured)
            {
                openCodeFailureCount = 0;
                ApplyRow(row5h, go, go.Rolling, false);
                ApplyRow(rowWeek, go, go.Weekly, false);
                ApplyRow(rowMonth, go, go.Monthly, false);
            }
            else if (!go.Ok)
            {
                openCodeFailureCount++;
                if (cfg.OpenCodeCacheKnown)
                {
                    GoState cached = CachedOpenCodeState();
                    ApplyCachedOpenCodeRows(cached);
                }
                else
                {
                    ApplyRow(row5h, go, go.Rolling, false);
                    ApplyRow(rowWeek, go, go.Weekly, false);
                    ApplyRow(rowMonth, go, go.Monthly, false);
                }
            }
            else
            {
                openCodeFailureCount = 0;
                openCodeLastSuccess = DateTime.Now;
                CacheOpenCode(go);
                ApplyRow(row5h, go, go.Rolling, false);
                ApplyRow(rowWeek, go, go.Weekly, false);
                ApplyRow(rowMonth, go, go.Monthly, false);
            }

            UpdateFetchTooltips();
            if (edgeHidden || hintAlpha > 0f) Invalidate();
        }

        private void RestoreOpenCodeCache()
        {
            if (!cfg.OpenCodeCacheKnown || cfg.OpenCodeKey.Length == 0) return;
            openCodeLastSuccess = LocalTimeFromUtcTicks(cfg.OpenCodeCacheUtcTicks);
            ApplyCachedOpenCodeRows(CachedOpenCodeState());
        }

        private void ApplyCachedOpenCodeRows(GoState cached)
        {
            ApplyRow(row5h, cached, cached.Rolling, true);
            ApplyRow(rowWeek, cached, cached.Weekly, true);
            ApplyRow(rowMonth, cached, cached.Monthly, true);
        }

        private GoState CachedOpenCodeState()
        {
            GoState go = new GoState { Configured = true, Ok = true };
            go.Rolling = CachedWindow(
                cfg.OpenCodeRollingUsed,
                cfg.OpenCodeRollingHasData,
                cfg.OpenCodeRollingRateLimited,
                cfg.OpenCodeRollingResetsUtcTicks);
            go.Weekly = CachedWindow(
                cfg.OpenCodeWeeklyUsed,
                cfg.OpenCodeWeeklyHasData,
                cfg.OpenCodeWeeklyRateLimited,
                cfg.OpenCodeWeeklyResetsUtcTicks);
            go.Monthly = CachedWindow(
                cfg.OpenCodeMonthlyUsed,
                cfg.OpenCodeMonthlyHasData,
                cfg.OpenCodeMonthlyRateLimited,
                cfg.OpenCodeMonthlyResetsUtcTicks);
            return go;
        }

        private static GoWindow CachedWindow(int used, bool hasData, bool rateLimited, long resetsUtcTicks)
        {
            GoWindow window = new GoWindow();
            window.Used = used;
            window.HasData = hasData;
            window.RateLimited = rateLimited;
            window.ResetsAt = FromUtcTicks(resetsUtcTicks);
            return window;
        }

        private void CacheOpenCode(GoState go)
        {
            cfg.OpenCodeCacheKnown = true;
            cfg.OpenCodeCacheUtcTicks = DateTime.UtcNow.Ticks;
            cfg.OpenCodeRollingUsed = go.Rolling.Used;
            cfg.OpenCodeRollingHasData = go.Rolling.HasData;
            cfg.OpenCodeRollingRateLimited = go.Rolling.RateLimited;
            cfg.OpenCodeRollingResetsUtcTicks = ToUtcTicks(go.Rolling.ResetsAt);
            cfg.OpenCodeWeeklyUsed = go.Weekly.Used;
            cfg.OpenCodeWeeklyHasData = go.Weekly.HasData;
            cfg.OpenCodeWeeklyRateLimited = go.Weekly.RateLimited;
            cfg.OpenCodeWeeklyResetsUtcTicks = ToUtcTicks(go.Weekly.ResetsAt);
            cfg.OpenCodeMonthlyUsed = go.Monthly.Used;
            cfg.OpenCodeMonthlyHasData = go.Monthly.HasData;
            cfg.OpenCodeMonthlyRateLimited = go.Monthly.RateLimited;
            cfg.OpenCodeMonthlyResetsUtcTicks = ToUtcTicks(go.Monthly.ResetsAt);
            cfg.Save();
        }

        private void ClearOpenCodeRows()
        {
            bool configured = cfg.OpenCodeKey.Length > 0;
            ResetRow(row5h, configured);
            ResetRow(rowWeek, configured);
            ResetRow(rowMonth, configured);
        }

        private void ResetRow(UsageRow row, bool configured)
        {
            row.Configured = configured;
            row.Error = "";
            row.RateLimited = false;
            row.Stale = false;
            row.ResetsAt = null;
            row.SetAnimatedRemaining(-1, clock.ElapsedMilliseconds, false);
            row.Invalidate();
        }

        private static string CurrencySymbol(string currency)
        {
            if (currency == "CNY") return "¥";
            if (currency == "USD") return "$";
            return string.IsNullOrEmpty(currency) ? "" : currency + " ";
        }

        private void ApplyRow(UsageRow row, GoState go, GoWindow w, bool stale)
        {
            row.Configured = go.Configured;
            row.Error = go.Ok ? "" : go.Error;
            row.RateLimited = go.Ok && w.RateLimited;
            row.Stale = stale;
            row.ResetsAt = go.Ok ? w.ResetsAt : null;
            int remaining = go.Ok && w.HasData && !w.RateLimited
                ? Math.Max(0, UiMetrics.PercentMax - w.Used) : -1;
            if (go.Ok && w.RateLimited) remaining = 0;
            row.SetAnimatedRemaining(remaining, clock.ElapsedMilliseconds, !edgeHidden);
            row.Invalidate();
        }

        private static DeepSeekState FetchDeepSeek(string key)
        {
            DeepSeekState st = new DeepSeekState();
            if (string.IsNullOrEmpty(key)) return st;
            st.Configured = true;
            int status = 0;
            try
            {
                string json = HttpGet("https://api.deepseek.com/user/balance", key, out status);
                JavaScriptSerializer js = new JavaScriptSerializer();
                Dictionary<string, object> root = js.DeserializeObject(json) as Dictionary<string, object>;
                if (root == null) { st.Error = Strings.ResponseParseFailed; return st; }
                if (root.ContainsKey("is_available") && !Convert.ToBoolean(root["is_available"]))
                {
                    st.Error = Strings.AccountUnavailable;
                    return st;
                }
                object[] infos = root.ContainsKey("balance_infos") ? root["balance_infos"] as object[] : null;
                if (infos == null || infos.Length == 0) { st.Error = Strings.NoBalanceInfo; return st; }
                Dictionary<string, object> pick = null;
                foreach (object it in infos)
                {
                    Dictionary<string, object> d = it as Dictionary<string, object>;
                    if (d == null) continue;
                    if (pick == null) pick = d;
                    if (GetString(d, "currency") == "CNY") { pick = d; break; }
                }
                if (pick == null) { st.Error = Strings.NoBalanceInfo; return st; }
                st.Currency = GetString(pick, "currency");
                st.Total = GetDecimal(pick, "total_balance");
                st.Ok = true;
            }
            catch (Exception ex)
            {
                st.Error = MapError(status, ex);
            }
            return st;
        }

        private static GoState FetchGo(string key)
        {
            GoState st = new GoState();
            if (string.IsNullOrEmpty(key)) return st;
            st.Configured = true;

            string json = null;
            int status = 0;
            Exception last = null;
            string[] urls = new string[]
            {
                "https://opencode.ai/zen/go/v1/usage",
                "https://opencode.ai/inference/go/v1/usage"
            };
            foreach (string url in urls)
            {
                try
                {
                    json = HttpGet(url, key, out status);
                    last = null;
                    break;
                }
                catch (Exception ex)
                {
                    last = ex;
                    if (status != (int)HttpStatusCode.NotFound) break;
                }
            }
            if (json == null)
            {
                st.Error = MapError(status, last);
                return st;
            }

            try
            {
                JavaScriptSerializer js = new JavaScriptSerializer();
                Dictionary<string, object> root = js.DeserializeObject(json) as Dictionary<string, object>;
                if (root == null || !root.ContainsKey("usage")) { st.Error = Strings.MissingUsage; return st; }
                Dictionary<string, object> usage = root["usage"] as Dictionary<string, object>;
                if (usage == null) { st.Error = Strings.MissingUsage; return st; }
                st.Rolling = ParseWindow(usage, "rolling");
                st.Weekly = ParseWindow(usage, "weekly");
                st.Monthly = ParseWindow(usage, "monthly");
                st.Ok = true;
            }
            catch (Exception ex)
            {
                st.Error = Strings.ParseFailed(ex.Message);
            }
            return st;
        }

        private static GoWindow ParseWindow(Dictionary<string, object> usage, string name)
        {
            GoWindow w = new GoWindow();
            object raw;
            if (!usage.TryGetValue(name, out raw)) return w;
            Dictionary<string, object> d = raw as Dictionary<string, object>;
            if (d == null) return w;
            w.HasData = true;
            if (d.ContainsKey("percent"))
                w.Used = (int)Math.Round(Math.Max(0, Math.Min(UiMetrics.PercentMax,
                    GetDouble(d, "percent"))));
            else if (d.ContainsKey("used") && d.ContainsKey("limit"))
            {
                double limit = GetDouble(d, "limit");
                if (limit > 0)
                    w.Used = (int)Math.Round(Math.Max(0, Math.Min(UiMetrics.PercentMax,
                        GetDouble(d, "used") * UiMetrics.PercentMax / limit)));
            }
            if (d.ContainsKey("status"))
                w.RateLimited = string.Equals(GetString(d, "status"), "rate-limited", StringComparison.OrdinalIgnoreCase);
            if (d.ContainsKey("resetsAt"))
                w.ResetsAt = ParseTime(d["resetsAt"]);
            return w;
        }

        private static DateTimeOffset? ParseTime(object o)
        {
            string s = o as string;
            if (string.IsNullOrEmpty(s)) return null;
            DateTimeOffset dto;
            if (DateTimeOffset.TryParse(s, CultureInfo.InvariantCulture,
                DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out dto))
                return dto;
            return null;
        }

        private static string HttpGet(string url, string key, out int status)
        {
            status = 0;
            HttpWebRequest req = (HttpWebRequest)WebRequest.Create(url);
            req.Method = "GET";
            req.UserAgent = "QuotaFloat/1.0";
            req.Headers["Authorization"] = "Bearer " + key;
            req.Accept = "application/json";
            req.Timeout = Timing.NetworkTimeoutMilliseconds;
            req.ReadWriteTimeout = Timing.NetworkTimeoutMilliseconds;
            try
            {
                using (HttpWebResponse resp = (HttpWebResponse)req.GetResponse())
                {
                    status = (int)resp.StatusCode;
                    using (StreamReader sr = new StreamReader(resp.GetResponseStream(), Encoding.UTF8))
                        return sr.ReadToEnd();
                }
            }
            catch (WebException we)
            {
                HttpWebResponse hr = we.Response as HttpWebResponse;
                if (hr != null) status = (int)hr.StatusCode;
                throw;
            }
        }

        private static string MapError(int status, Exception ex)
        {
            if (status == (int)HttpStatusCode.Unauthorized) return Strings.InvalidKey(status);
            if (status == (int)HttpStatusCode.PaymentRequired) return Strings.InsufficientBalance(status);
            if (status == (int)HttpStatusCode.Forbidden) return Strings.Forbidden(status);
            if (status == NetworkMetrics.TooManyRequestsStatus) return Strings.TooManyRequests(status);
            if (status > 0) return "HTTP " + status.ToString(CultureInfo.InvariantCulture);
            WebException we = ex as WebException;
            if (we != null)
            {
                if (we.Status == WebExceptionStatus.Timeout) return Strings.Timeout;
                if (we.Status == WebExceptionStatus.NameResolutionFailure) return Strings.DnsFailure;
                if (we.Status == WebExceptionStatus.ConnectFailure) return Strings.ConnectFailure;
            }
            return Strings.NetworkError;
        }

        private static string GetString(Dictionary<string, object> d, string k)
        {
            object v;
            return d.TryGetValue(k, out v) && v != null ? Convert.ToString(v, CultureInfo.InvariantCulture) : "";
        }

        private static decimal GetDecimal(Dictionary<string, object> d, string k)
        {
            object v;
            if (!d.TryGetValue(k, out v) || v == null) return 0m;
            try { return Convert.ToDecimal(v, CultureInfo.InvariantCulture); }
            catch { return 0m; }
        }

        private static double GetDouble(Dictionary<string, object> d, string k)
        {
            object v;
            if (!d.TryGetValue(k, out v) || v == null) return 0;
            try { return Convert.ToDouble(v, CultureInfo.InvariantCulture); }
            catch { return 0; }
        }
    }
}

