// ---- source: MainForm.Edge.cs ----
namespace QuotaFloat
{
    using System;
    using System.Collections.Generic;
    using System.Drawing;
    using System.Drawing.Drawing2D;
    using System.Globalization;
    using System.IO;
    using System.Net;
    using System.Runtime.InteropServices;
    using System.Security.Cryptography;
    using System.Text;
    using System.Threading.Tasks;
    using System.Web.Script.Serialization;
    using System.Windows.Forms;
    using Microsoft.Win32;
    internal sealed partial class MainForm
    {
        // ---------- 贴边滑出 / 悬停恢复 ----------
        private int DockEdge()
        {
            Rectangle wa = Screen.FromControl(this).WorkingArea;
            int dl = Math.Max(0, Left - wa.Left);
            int dr = Math.Max(0, wa.Right - Right);
            int dt = Math.Max(0, Top - wa.Top);
            int db = Math.Max(0, wa.Bottom - Bottom);
            int min = Math.Min(Math.Min(dl, dr), Math.Min(dt, db));
            if (min > EdgeMetrics.DockTolerance) return EdgeMetrics.DockNone;
            if (min == dl) return EdgeMetrics.DockLeft;
            if (min == dr) return EdgeMetrics.DockRight;
            if (min == dt) return EdgeMetrics.DockTop;
            return EdgeMetrics.DockBottom;
        }

        private Point VisibleLocation()
        {
            Rectangle wa = Screen.FromControl(this).WorkingArea;
            if (dockedEdge == EdgeMetrics.DockLeft) return new Point(wa.Left, Top);
            if (dockedEdge == EdgeMetrics.DockRight) return new Point(wa.Right - Width, Top);
            if (dockedEdge == EdgeMetrics.DockTop) return new Point(Left, wa.Top);
            if (dockedEdge == EdgeMetrics.DockBottom) return new Point(Left, wa.Bottom - Height);
            return Location;
        }

        private Point HiddenLocation()
        {
            Rectangle wa = Screen.FromControl(this).WorkingArea;
            if (dockedEdge == EdgeMetrics.DockLeft) return new Point(wa.Left - Width + EdgeMetrics.Strip, Top);
            if (dockedEdge == EdgeMetrics.DockRight) return new Point(wa.Right - EdgeMetrics.Strip, Top);
            if (dockedEdge == EdgeMetrics.DockTop) return new Point(Left, wa.Top - Height + EdgeMetrics.Strip);
            if (dockedEdge == EdgeMetrics.DockBottom) return new Point(Left, wa.Bottom - EdgeMetrics.Strip);
            return Location;
        }

        private Point EdgeLocation(int edge, double anchor, Rectangle wa)
        {
            int x = Left;
            int y = Top;
            if (edge == EdgeMetrics.DockLeft || edge == EdgeMetrics.DockRight)
            {
                x = edge == EdgeMetrics.DockLeft ? wa.Left : wa.Right - Width;
                y = wa.Top + (int)Math.Round(anchor * wa.Height) - Height / 2;
            }
            else
            {
                y = edge == EdgeMetrics.DockTop ? wa.Top : wa.Bottom - Height;
                x = wa.Left + (int)Math.Round(anchor * wa.Width) - Width / 2;
            }
            if (x < wa.Left) x = wa.Left;
            if (y < wa.Top) y = wa.Top;
            if (x + Width > wa.Right) x = wa.Right - Width;
            if (y + Height > wa.Bottom) y = wa.Bottom - Height;
            return new Point(x, y);
        }

        private double EdgeAnchorFor(int edge, Rectangle wa)
        {
            double anchor;
            if (edge == EdgeMetrics.DockLeft || edge == EdgeMetrics.DockRight)
                anchor = (Top + Height / 2.0 - wa.Top) / Math.Max(1.0, wa.Height);
            else
                anchor = (Left + Width / 2.0 - wa.Left) / Math.Max(1.0, wa.Width);
            if (anchor < EdgeMetrics.AnchorMin) anchor = EdgeMetrics.AnchorMin;
            if (anchor > EdgeMetrics.AnchorMax) anchor = EdgeMetrics.AnchorMax;
            return anchor;
        }

        private void SaveDockState()
        {
            if (dockedEdge == EdgeMetrics.DockNone)
            {
                cfg.EdgeDock = EdgeMetrics.DockNone;
                return;
            }
            Rectangle wa = Screen.FromControl(this).WorkingArea;
            cfg.EdgeDock = dockedEdge;
            cfg.EdgeAnchor = EdgeAnchorFor(dockedEdge, wa);
        }

        private void TickEdge()
        {
            if (!cfg.EdgeHide || dockedEdge == EdgeMetrics.DockNone) return;
            if (menu.Visible || refreshingPaused || editingField != UiMetrics.EquationFieldNone || resizing)
            {
                lastInside = DateTime.UtcNow;
                hiddenHoverStart = DateTime.MinValue;
                return;
            }
            if (slideAnimating) return;

            bool inside = Bounds.Contains(Cursor.Position);
            DateTime now = DateTime.UtcNow;
            if (inside)
            {
                lastInside = now;
                edgeArmed = true;
                if (edgeHidden)
                {
                    if (hiddenHoverStart == DateTime.MinValue) hiddenHoverStart = now;
                    if ((now - hiddenHoverStart).TotalMilliseconds >= Timing.ShowDelayMilliseconds) ShowEdge();
                }
                else
                {
                    hiddenHoverStart = DateTime.MinValue;
                }
            }
            else
            {
                hiddenHoverStart = DateTime.MinValue;
                if (edgeArmed && !edgeHidden)
                {
                    if (now >= hideNotBefore &&
                        (now - lastInside).TotalMilliseconds >= Timing.HideDelayMilliseconds)
                        HideEdge();
                }
            }
        }

        private void StartSlide(bool hide)
        {
            if (dockedEdge == EdgeMetrics.DockNone) return;
            if (hide && !cfg.EdgeHide) return;
            SetHighResolutionTimer(true);
            hiddenHoverStart = DateTime.MinValue;
            Point target = hide ? HiddenLocation() : VisibleLocation();
            if (Location == target)
            {
                slideAnimating = false;
                slideTimer.Stop();
                slideOutTarget = hide;
                edgeHidden = hide;
                hintAlpha = hide ? 1f : 0f;
                if (!hide)
                {
                    hideNotBefore = DateTime.MinValue;
                    lastInside = DateTime.UtcNow;
                }
                Invalidate();
                return;
            }
            slideFrom = Location;
            slideTo = target;
            slideOutTarget = hide;
            slideAnimating = true;
            slideStartStamp = clock.ElapsedTicks;
            hintFrom = hintAlpha;
            hintTo = hide ? 1f : 0f;
            if (!hide)
            {
                edgeHidden = false;
                hideNotBefore = DateTime.MinValue;
                lastInside = DateTime.UtcNow;
            }
            slideTimer.Start();
        }

        private void ShowEdge()
        {
            StartSlide(false);
            RefreshIfStaleOnReveal();
        }

        private void HideEdge()
        {
            StartSlide(true);
        }

        private void TickSlide()
        {
            if (!slideAnimating)
            {
                slideTimer.Stop();
                return;
            }
            double elapsed = ElapsedMilliseconds(slideStartStamp);
            float t = (float)(elapsed / Timing.SlideDurationMilliseconds);
            if (t >= 1f)
            {
                Location = slideTo;
                slideAnimating = false;
                slideTimer.Stop();
                edgeHidden = slideOutTarget;
                hintAlpha = hintTo;
                if (!edgeHidden) lastInside = DateTime.UtcNow;
                SyncHighResolutionTimer();
                Invalidate();
                return;
            }
            float ease = Ui.EaseOut(t);
            int x = slideFrom.X + (int)Math.Round((slideTo.X - slideFrom.X) * ease);
            int y = slideFrom.Y + (int)Math.Round((slideTo.Y - slideFrom.Y) * ease);
            Location = new Point(x, y);
            hintAlpha = hintFrom + (hintTo - hintFrom) * ease;
            Invalidate();
        }

        private void ApplyEdgeHideSetting()
        {
            if (!cfg.EdgeHide)
            {
                slideTimer.Stop();
                slideAnimating = false;
                slideOutTarget = false;
                if (dockedEdge != EdgeMetrics.DockNone)
                {
                    Location = VisibleLocation();
                    edgeHidden = false;
                }
                hiddenHoverStart = DateTime.MinValue;
                hideNotBefore = DateTime.MinValue;
                hintAlpha = 0f;
                edgeTimer.Stop();
                SyncHighResolutionTimer();
                Invalidate();
                return;
            }

            dockedEdge = DockEdge();
            edgeHidden = false;
            hiddenHoverStart = DateTime.MinValue;
            hideNotBefore = DateTime.MinValue;
            if (dockedEdge != EdgeMetrics.DockNone)
            {
                Location = VisibleLocation();
                edgeArmed = true;
                lastInside = DateTime.UtcNow;
                edgeTimer.Start();
            }
            SyncHighResolutionTimer();
            Invalidate();
        }

        private void EnsureEdgeVisible()
        {
            if (dockedEdge == EdgeMetrics.DockNone) return;
            if (!edgeHidden && !(slideAnimating && slideOutTarget)) return;
            slideTimer.Stop();
            slideAnimating = false;
            slideOutTarget = false;
            edgeHidden = false;
            hiddenHoverStart = DateTime.MinValue;
            hideNotBefore = DateTime.MinValue;
            hintAlpha = 0f;
            Location = VisibleLocation();
            lastInside = DateTime.UtcNow;
            SyncHighResolutionTimer();
            Invalidate();
        }

        private void ApplyRoundedRegion()
        {
            if (Width <= 0 || Height <= 0) return;
            using (GraphicsPath p = Ui.Rounded(new Rectangle(0, 0, Width, Height),
                UiMetrics.WindowCornerRadius))
            {
                Region old = Region;
                Region = new Region(p);
                if (old != null) old.Dispose();
            }
        }

        private bool HasOpenCodeEdgeUsage()
        {
            return cfg.ShowOpenCode && row5h.Configured &&
                   row5h.Error.Length == 0 && row5h.Remaining >= 0;
        }

        private bool HasDeepSeekEdgeUsage()
        {
            return cfg.ShowDeepSeek && lastDeepSeekBalanceKnown;
        }

        private int EdgeDisplayPercent()
        {
            if (HasOpenCodeEdgeUsage())
                return row5h.RateLimited ? 0 : Math.Max(0, Math.Min(UiMetrics.PercentMax, row5h.Remaining));
            if (HasDeepSeekEdgeUsage())
            {
                float remaining;
                if (cfg.DeepSeekHasTotal && cfg.DeepSeekTotal > 0m)
                    remaining = (float)(lastDeepSeekBalance * UiMetrics.PercentMax / cfg.DeepSeekTotal);
                else
                    remaining = lastDeepSeekBalance > 0m ? UiMetrics.PercentMax : 0f;
                return Math.Max(0, Math.Min(UiMetrics.PercentMax, (int)Math.Round(remaining)));
            }
            return -1;
        }

        private Color EdgeDisplayColor()
        {
            if (HasOpenCodeEdgeUsage())
                return row5h.RateLimited ? Palette.Red : Ui.LevelColor(row5h.Remaining);
            if (HasDeepSeekEdgeUsage()) return Palette.Blue;
            return Palette.Sub;
        }

        private void PaintEdgeHint(Graphics g)
        {
            if (!cfg.EdgeHide || dockedEdge == EdgeMetrics.DockNone || hintAlpha <= EdgeMetrics.HintVisibleThreshold) return;
            int a = (int)Math.Round(EdgeMetrics.ColorAlphaMax *
                Math.Max(0f, Math.Min(1f, hintAlpha)));
            if (a <= 0) return;

            int pct = EdgeDisplayPercent();
            int len = EdgeMetrics.HintLength;
            int thick = EdgeMetrics.HintThickness;
            int x = 0;
            int y = 0;
            int w = 0;
            int h = 0;
            bool vertical = dockedEdge == EdgeMetrics.DockLeft || dockedEdge == EdgeMetrics.DockRight;
            if (dockedEdge == EdgeMetrics.DockRight)
            {
                len = Math.Max(EdgeMetrics.HintMinLength, Height - EdgeMetrics.HintEndInset);
                x = EdgeMetrics.HintEdgeInset;
                y = (Height - len) / 2;
                w = thick;
                h = len;
            }
            else if (dockedEdge == EdgeMetrics.DockLeft)
            {
                len = Math.Max(EdgeMetrics.HintMinLength, Height - EdgeMetrics.HintEndInset);
                x = Width - EdgeMetrics.HintOppositeInset;
                y = (Height - len) / 2;
                w = thick;
                h = len;
            }
            else if (dockedEdge == EdgeMetrics.DockBottom)
            {
                len = Math.Max(EdgeMetrics.HintMinLength, Width - EdgeMetrics.HintEndInset);
                x = (Width - len) / 2;
                y = EdgeMetrics.HintEdgeInset;
                w = len;
                h = thick;
            }
            else
            {
                len = Math.Max(EdgeMetrics.HintMinLength, Width - EdgeMetrics.HintEndInset);
                x = (Width - len) / 2;
                y = Height - EdgeMetrics.HintOppositeInset;
                w = len;
                h = thick;
            }
            if (x < 0) x = 0;
            if (y < 0) y = 0;
            if (x + w > Width) x = Width - w;
            if (y + h > Height) y = Height - h;

            int segments;
            int gap;
            int gridStep;
            if (vertical)
            {
                segments = EdgeMetrics.VerticalSegments;
                gap = EdgeMetrics.VerticalGap;
                gridStep = 0;
            }
            else
            {
                segments = len >= EdgeMetrics.HorizontalLongThreshold
                    ? EdgeMetrics.HorizontalLongSegments : EdgeMetrics.HorizontalShortSegments;
                gap = EdgeMetrics.HorizontalGap;
                gridStep = segments == EdgeMetrics.HorizontalLongSegments
                    ? EdgeMetrics.HorizontalLongGrid : EdgeMetrics.HorizontalShortGrid;
            }
            double step = (double)UiMetrics.PercentMax / segments;
            int usable = len - gap * (segments - 1);
            if (usable < segments)
            {
                gap = 0;
                usable = len;
            }
            int segLen = Math.Max(1, usable / segments);
            int used = segLen * segments + gap * (segments - 1);
            int origin = (vertical ? y : x) + (len - used) / 2;
            int bottom = origin + used;
            int subDivisions = gridStep > 0 ? (UiMetrics.PercentMax / segments) / gridStep : 1;
            Color fillColor = Color.FromArgb(a, EdgeDisplayColor());

            using (SolidBrush tb = new SolidBrush(Color.FromArgb(a, Palette.Track)))
            using (SolidBrush fb = new SolidBrush(fillColor))
            using (Pen subTick = new Pen(Color.FromArgb(EdgeMetrics.SubTickAlpha, Palette.Bg),
                EdgeMetrics.SubTickWidth))
            {
                for (int i = 0; i < segments; i++)
                {
                    Rectangle track;
                    if (vertical)
                    {
                        int blockBottom = bottom - i * (segLen + gap);
                        track = new Rectangle(x, blockBottom - segLen, thick, segLen);
                    }
                    else
                    {
                        int blockLeft = origin + i * (segLen + gap);
                        track = new Rectangle(blockLeft, y, segLen, thick);
                    }

                    using (GraphicsPath tp = Ui.Rounded(track, EdgeMetrics.SegmentRadius))
                        g.FillPath(tb, tp);

                    double fraction = Math.Max(0.0, Math.Min(1.0, (pct - i * step) / step));
                    if (fraction > 0.0)
                    {
                        int fillLen = (int)Math.Round(segLen * fraction);
                        if (fillLen < 1) fillLen = 1;
                        if (fillLen > segLen) fillLen = segLen;

                        Rectangle fill;
                        if (vertical)
                            fill = new Rectangle(x, track.Bottom - fillLen, thick, fillLen);
                        else
                            fill = new Rectangle(track.X, y, fillLen, thick);

                        using (GraphicsPath fp = Ui.Rounded(fill, EdgeMetrics.SegmentRadius))
                            g.FillPath(fb, fp);
                    }

                    if (segLen >= EdgeMetrics.SegmentMinLengthForTicks)
                    {
                        for (int j = 1; j < subDivisions; j++)
                        {
                            if (vertical)
                            {
                                int pos = track.Bottom -
                                    (int)Math.Round(track.Height * (double)j / subDivisions);
                                g.DrawLine(subTick, x + EdgeMetrics.SubTickInset, pos,
                                    x + thick - EdgeMetrics.SubTickEndInset, pos);
                            }
                            else
                            {
                                int pos = track.X +
                                    (int)Math.Round(track.Width * (double)j / subDivisions);
                                g.DrawLine(subTick, pos, y + EdgeMetrics.SubTickInset,
                                    pos, y + thick - EdgeMetrics.SubTickEndInset);
                            }
                        }
                    }
                }
            }
        }
    }
}

// ---- source: MainForm.UI.cs ----
namespace QuotaFloat
{
    using System;
    using System.Collections.Generic;
    using System.Drawing;
    using System.Drawing.Drawing2D;
    using System.Globalization;
    using System.IO;
    using System.Net;
    using System.Runtime.InteropServices;
    using System.Security.Cryptography;
    using System.Text;
    using System.Threading.Tasks;
    using System.Web.Script.Serialization;
    using System.Windows.Forms;
    using Microsoft.Win32;
    internal sealed partial class MainForm
    {
        // ---------- 等式内联编辑 ----------
        private void ValueMouseDown(int field)
        {
            if (!cfg.EquationEnabled || !equationPanel.Visible) return;
            if (editingField != UiMetrics.EquationFieldNone)
            {
                EndEdit(true);
                return;
            }
            DateTime now = DateTime.UtcNow;
            if (lastValueField == field &&
                (now - lastValueClick).TotalMilliseconds <= Timing.ValueClickWindowMilliseconds)
            {
                lastValueField = UiMetrics.EquationFieldNone;
                BeginEdit(field);
            }
            else
            {
                lastValueField = field;
                lastValueClick = now;
            }
        }

        private void BeginEdit(int field)
        {
            if (!cfg.EquationEnabled || !equationPanel.Visible) return;
            if (!lastDeepSeekBalanceKnown || editingField != UiMetrics.EquationFieldNone) return;
            Label target = field == UiMetrics.EquationFieldSpent ? spentLabel : totalLabel;
            editingField = field;
            inlineEditor.Bounds = target.Bounds;
            inlineEditor.Text = target.Text == "—" ? "" : target.Text;
            target.Visible = false;
            inlineEditor.Visible = true;
            refreshingPaused = true;
            inlineEditor.Focus();
            inlineEditor.SelectionStart = 0;
            inlineEditor.SelectionLength = inlineEditor.Text.Length;
        }

        private void EditorKeyDown(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Enter)
            {
                EndEdit(true);
                e.SuppressKeyPress = true;
            }
            else if (e.KeyCode == Keys.Escape)
            {
                EndEdit(false);
                e.SuppressKeyPress = true;
            }
        }

        private void EndEdit(bool commit)
        {
            if (editingField == UiMetrics.EquationFieldNone) return;
            int field = editingField;
            editingField = UiMetrics.EquationFieldNone;

            if (commit && lastDeepSeekBalanceKnown)
            {
                string text = inlineEditor.Text.Trim();
                if (field == UiMetrics.EquationFieldTotal)
                {
                    if (text.Length == 0)
                    {
                        cfg.DeepSeekHasTotal = false;
                        cfg.DeepSeekTotal = 0m;
                    }
                    else
                    {
                        decimal t;
                        if (TryParseDecimal(text, out t) && t >= 0m)
                        {
                            cfg.DeepSeekTotal = t;
                            cfg.DeepSeekHasTotal = t > 0m;
                        }
                    }
                }
                else
                {
                    decimal s;
                    if (text.Length > 0 && TryParseDecimal(text, out s) && s >= 0m)
                    {
                        decimal t = lastDeepSeekBalance + s;
                        cfg.DeepSeekTotal = t;
                        cfg.DeepSeekHasTotal = t > 0m;
                    }
                }
                cfg.DeepSeekBalance = lastDeepSeekBalance;
                cfg.DeepSeekCurrency = lastDeepSeekCurrency;
                cfg.DeepSeekBalanceKnown = true;
                cfg.DeepSeekSpent = cfg.DeepSeekHasTotal
                    ? Math.Max(0m, cfg.DeepSeekTotal - lastDeepSeekBalance)
                    : 0m;
                cfg.Save();
            }

            inlineEditor.Visible = false;
            spentLabel.Visible = true;
            totalLabel.Visible = true;
            refreshingPaused = false;
            UpdateDisplay();
        }

        private void UpdateDisplay()
        {
            if (!lastDeepSeekBalanceKnown)
            {
                equationPanel.Visible = false;
                deepSeekBalanceOnly.Visible = false;
                deepSeekStatus.Visible = true;
                return;
            }
            if (cfg.EquationEnabled)
            {
                equationPanel.Visible = true;
                deepSeekBalanceOnly.Visible = false;
                deepSeekStatus.Visible = false;
                UpdateEquationFields();
            }
            else
            {
                equationPanel.Visible = false;
                deepSeekBalanceOnly.Visible = true;
                deepSeekStatus.Visible = false;
                string sym = CurrencySymbol(lastDeepSeekCurrency);
                deepSeekBalanceOnly.Text = sym + " " + lastDeepSeekBalance.ToString("0.00", CultureInfo.InvariantCulture);
            }
        }

        private void UpdateEquationFields()
        {
            if (!lastDeepSeekBalanceKnown) return;
            string sym = CurrencySymbol(lastDeepSeekCurrency);
            deepSeekBalance.Text = sym + " " + lastDeepSeekBalance.ToString("0.00", CultureInfo.InvariantCulture);
            float barTarget;
            if (cfg.DeepSeekHasTotal)
            {
                decimal s = cfg.DeepSeekTotal - lastDeepSeekBalance;
                if (s < 0m) s = 0m;
                spentLabel.Text = s.ToString("0.00", CultureInfo.InvariantCulture);
                totalLabel.Text = cfg.DeepSeekTotal.ToString("0.00", CultureInfo.InvariantCulture);
                barTarget = cfg.DeepSeekTotal > 0m
                    ? (float)(lastDeepSeekBalance * UiMetrics.PercentMax / cfg.DeepSeekTotal) : 0f;
            }
            else
            {
                spentLabel.Text = "0";
                totalLabel.Text = lastDeepSeekBalance.ToString("0.00", CultureInfo.InvariantCulture);
                barTarget = lastDeepSeekBalance > 0m ? UiMetrics.PercentMax : 0f;
            }
            dsBar.SetAnimatedPercent(barTarget, clock.ElapsedMilliseconds, !edgeHidden);
            LayoutEquation();
        }

        private static bool TryParseDecimal(string s, out decimal v)
        {
            if (decimal.TryParse(s, NumberStyles.Number, CultureInfo.CurrentCulture, out v)) return true;
            return decimal.TryParse(s, NumberStyles.Number, CultureInfo.InvariantCulture, out v);
        }

        // ---------- 主题 ----------
        private bool ResolveLightTheme()
        {
            if (cfg.ThemeMode == AppConfig.ThemeLight) return true;
            if (cfg.ThemeMode == AppConfig.ThemeDark) return false;
            return IsSystemLightTheme();
        }

        private static bool IsSystemLightTheme()
        {
            try
            {
                object value = Registry.GetValue(
                    @"HKEY_CURRENT_USER\Software\Microsoft\Windows\CurrentVersion\Themes\Personalize",
                    "AppsUseLightTheme", 0);
                return value != null && Convert.ToInt32(value) != 0;
            }
            catch { return false; }
        }

        private void SetThemeMode(int mode)
        {
            cfg.ThemeMode = mode;
            cfg.Save();
            ApplyTheme(mode == AppConfig.ThemeFollowSystem
                ? IsSystemLightTheme() : mode == AppConfig.ThemeLight);
        }

        private void ApplyTheme(bool light)
        {
            if (lightTheme == light) return;
            Color oldSub = Palette.Sub;
            Color oldText = Palette.Text;
            Color oldRed = Palette.Red;
            Color oldGreen = Palette.Green;
            Color oldYellow = Palette.Yellow;
            Color oldCard = Palette.Card;

            Palette.Apply(light);
            lightTheme = light;
            BackColor = Palette.Bg;

            dsBar.FillColor = Palette.Blue;
            refreshBar.FillColor = Palette.Red;
            RecolorControls(this, oldSub, oldText, oldRed, oldGreen, oldYellow, oldCard);
            Invalidate(true);
        }

        private void RecolorControls(Control parent, Color oldSub, Color oldText,
            Color oldRed, Color oldGreen, Color oldYellow, Color oldCard)
        {
            foreach (Control c in parent.Controls)
            {
                if (c is Label)
                {
                    Color f = c.ForeColor;
                    if (f == oldSub) c.ForeColor = Palette.Sub;
                    else if (f == oldText) c.ForeColor = Palette.Text;
                    else if (f == oldRed) c.ForeColor = Palette.Red;
                    else if (f == oldGreen) c.ForeColor = Palette.Green;
                    else if (f == oldYellow) c.ForeColor = Palette.Yellow;
                    if (c.BackColor == oldCard) c.BackColor = Palette.Card;
                }
                else if (c is TextBox)
                {
                    if (c.BackColor == oldCard) c.BackColor = Palette.Card;
                    if (c.ForeColor == oldText) c.ForeColor = Palette.Text;
                }
                else if (c is Card || c is UsageRow || c is MiniBar || c is RefreshButton || c is Panel)
                {
                    if (c == refreshBar) c.BackColor = Palette.Bg;
                    else if (c.BackColor == oldCard) c.BackColor = Palette.Card;
                    c.Invalidate();
                }
                RecolorControls(c, oldSub, oldText, oldRed, oldGreen, oldYellow, oldCard);
            }
        }

        private static bool IsAutoStartEnabled()
        {
            try
            {
                using (RegistryKey k = Registry.CurrentUser.OpenSubKey(
                    @"Software\Microsoft\Windows\CurrentVersion\Run", false))
                {
                    return k != null && k.GetValue("QuotaFloat") != null;
                }
            }
            catch { return false; }
        }

        private static bool SetAutoStart(bool enabled)
        {
            try
            {
                using (RegistryKey k = Registry.CurrentUser.CreateSubKey(
                    @"Software\Microsoft\Windows\CurrentVersion\Run"))
                {
                    if (k == null) return false;
                    if (enabled)
                        k.SetValue("QuotaFloat", "\"" + Application.ExecutablePath + "\"",
                            RegistryValueKind.String);
                    else
                        k.DeleteValue("QuotaFloat", false);
                }
                return true;
            }
            catch (Exception ex)
            {
                MessageBox.Show(Strings.AutoStartFailed(ex.Message), "QuotaFloat",
                    MessageBoxButtons.OK, MessageBoxIcon.Warning);
                return false;
            }
        }

        private void ApplyLanguage()
        {
            Text = demoMode ? Strings.AppTitleDemo : Strings.AppTitle;
            row5h.Caption = Strings.FiveHours;
            rowWeek.Caption = Strings.ThisWeek;
            rowMonth.Caption = Strings.ThisMonth;
            row5h.Invalidate();
            rowWeek.Invalidate();
            rowMonth.Invalidate();

            peakState = null;
            UpdatePeakBadge();

            if (!lastDeepSeekBalanceKnown)
            {
                deepSeekStatus.Text = cfg.DeepSeekKey.Length == 0
                    ? Strings.NotConfiguredHint
                    : Strings.Loading;
            }
            else
            {
                UpdateDisplay();
            }

            if (!demoMode)
            {
                lastDeepSeekFetchStamp = Timing.NoStamp;
                lastOpenCodeFetchStamp = Timing.NoStamp;
                StartFetch();
            }
            ApplyTooltips();
            Invalidate(true);
        }

        private void ApplyTooltips()
        {
            tips.ShowAlways = true;
            tips.SetToolTip(this, Strings.WindowTip);
            tips.SetToolTip(dsCard, Strings.DeepSeekCardTip);
            tips.SetToolTip(dsTitle, Strings.DeepSeekTitleTip);
            tips.SetToolTip(deepSeekPeriod, Strings.DeepSeekPeriodTip);
            tips.SetToolTip(deepSeekStatus, Strings.DeepSeekStatusTip);
            tips.SetToolTip(deepSeekBalanceOnly, Strings.DeepSeekBalanceTip);
            tips.SetToolTip(equationPanel, Strings.EquationTip);
            tips.SetToolTip(deepSeekBalance, Strings.BalanceTip);
            tips.SetToolTip(plusLabel, Strings.PlusTip);
            tips.SetToolTip(spentLabel, Strings.SpentTip);
            tips.SetToolTip(equalsLabel, Strings.EqualsTip);
            tips.SetToolTip(totalLabel, Strings.TotalTip);
            tips.SetToolTip(dsBar, Strings.DeepSeekBarTip);
            tips.SetToolTip(refreshBar, Strings.RefreshBarTip);
            tips.SetToolTip(inlineEditor, Strings.InlineEditorTip);
            tips.SetToolTip(goCard, Strings.OpenCodeCardTip);
            tips.SetToolTip(goTitle, Strings.OpenCodeTitleTip);
            tips.SetToolTip(row5h, Strings.FiveHoursTip);
            tips.SetToolTip(rowWeek, Strings.WeekTip);
            tips.SetToolTip(rowMonth, Strings.MonthTip);
            UpdateFetchTooltips();
        }

        private void SetLanguage(string code)
        {
            code = Strings.Normalize(code);
            if (code == Strings.Code) return;
            Strings.Code = code;
            cfg.Language = code;
            cfg.Save();
            ApplyLanguage();
            if (IsHandleCreated && !IsDisposed)
                BeginInvoke(new Action(RebuildMenu));
        }

        private void RebuildMenu()
        {
            if (IsDisposed) return;
            ContextMenuStrip old = menu;
            menu = CreateMenu();
            ContextMenuStrip = menu;
            AttachMenu(this);
            if (old != null) old.Dispose();
        }

        private static bool HasArg(string name)
        {
            foreach (string arg in Environment.GetCommandLineArgs())
            {
                if (string.Equals(arg, name, StringComparison.OrdinalIgnoreCase)) return true;
            }
            return false;
        }

        // ---------- 调试 ----------
        private void ApplyDemo()
        {
            lastDeepSeekFetchStamp = clock.ElapsedTicks;
            lastOpenCodeFetchStamp = clock.ElapsedTicks;
            lastDeepSeekBalance = DemoData.DeepSeekBalance;
            lastDeepSeekCurrency = "CNY";
            lastDeepSeekBalanceKnown = true;
            cfg.DeepSeekTotal = DemoData.DeepSeekTotal;
            cfg.DeepSeekHasTotal = true;
            UpdateDisplay();

            row5h.Configured = true;
            row5h.Error = "";
            row5h.RateLimited = false;
            row5h.Remaining = DemoData.FiveHourRemaining;
            row5h.ResetsAt = DateTimeOffset.Now.AddHours(DemoData.FiveHourResetHours)
                .AddMinutes(DemoData.FiveHourResetMinutes)
                .AddSeconds(DemoData.FiveHourResetSeconds);
            row5h.Invalidate();

            rowWeek.Configured = true;
            rowWeek.Error = "";
            rowWeek.RateLimited = false;
            rowWeek.Remaining = DemoData.WeekRemaining;
            rowWeek.ResetsAt = DateTimeOffset.Now.AddDays(DemoData.WeekResetDays)
                .AddHours(DemoData.WeekResetHours)
                .AddMinutes(DemoData.WeekResetMinutes);
            rowWeek.Invalidate();

            rowMonth.Configured = true;
            rowMonth.Error = "";
            rowMonth.RateLimited = false;
            rowMonth.Remaining = DemoData.MonthRemaining;
            rowMonth.ResetsAt = DateTimeOffset.Now.AddDays(DemoData.MonthResetDays)
                .AddHours(DemoData.MonthResetHours);
            rowMonth.Invalidate();

            UpdatePeakBadge();
        }

        private void UpdatePeakBadge()
        {
            bool peak = IsPeakNow();
            if (peakState.HasValue && peakState.Value == peak) return;
            peakState = peak;
            deepSeekPeriod.Text = peak ? Strings.Peak : Strings.OffPeak;
            deepSeekPeriod.ForeColor = peak ? Palette.Red : Palette.Green;
        }

        private static bool IsPeakNow()
        {
            DateTimeOffset beijing = DateTimeOffset.UtcNow.ToOffset(
                TimeSpan.FromHours(PeakTime.BeijingUtcOffsetHours));
            DayOfWeek day = beijing.DayOfWeek;
            if (day == DayOfWeek.Saturday || day == DayOfWeek.Sunday) return false;
            TimeSpan time = beijing.TimeOfDay;
            return (time >= TimeSpan.FromHours(PeakTime.MorningStartHour) &&
                    time < TimeSpan.FromHours(PeakTime.MorningEndHour))
                || (time >= TimeSpan.FromHours(PeakTime.AfternoonStartHour) &&
                    time < TimeSpan.FromHours(PeakTime.AfternoonEndHour));
        }

        private void AttachDrag(Control c)
        {
            if (c == equationPanel) return;
            if (c is RefreshButton) return;
            if (!(c is TextBox)) c.MouseDown += DragWindow;
            foreach (Control child in c.Controls)
            {
                if (!(child is TextBox)) AttachDrag(child);
            }
        }

        private void AttachMenu(Control c)
        {
            if (!(c is TextBox)) c.ContextMenuStrip = menu;
            foreach (Control child in c.Controls)
            {
                if (!(child is TextBox)) AttachMenu(child);
            }
        }
    }
}

// ---- source: MainForm.Window.cs ----
namespace QuotaFloat
{
    using System;
    using System.Collections.Generic;
    using System.Drawing;
    using System.Drawing.Drawing2D;
    using System.Globalization;
    using System.IO;
    using System.Net;
    using System.Runtime.InteropServices;
    using System.Security.Cryptography;
    using System.Text;
    using System.Threading.Tasks;
    using System.Web.Script.Serialization;
    using System.Windows.Forms;
    using Microsoft.Win32;
    internal sealed partial class MainForm
    {
        // ---------- 窗口拖动 / 横向拉伸 ----------
        private void DragWindow(object sender, MouseEventArgs e)
        {
            if (e.Button != MouseButtons.Left) return;
            if (edgeHidden || (slideAnimating && slideOutTarget))
            {
                ShowEdge();
                return;
            }
            if (editingField != UiMetrics.EquationFieldNone)
            {
                EndEdit(true);
                return;
            }
            Point p = PointToClient(Cursor.Position);

            if (!cfg.WidthLocked && (p.X <= UiMetrics.ResizeLeftHotZone ||
                p.X >= ClientSize.Width - UiMetrics.ResizeRightHotZone))
            {
                resizeEdge = p.X <= UiMetrics.ResizeLeftHotZone
                    ? UiMetrics.ResizeDirectionLeft : UiMetrics.ResizeDirectionRight;
                resizeStartX = Cursor.Position.X;
                resizeStartBounds = Bounds;
                resizing = true;
                Capture = true;
                Cursor = Cursors.SizeWE;
                return;
            }

            if (cfg.EquationEnabled && equationPanel.Visible && lastDeepSeekBalanceKnown && editingField == UiMetrics.EquationFieldNone)
            {
                if (ValueRect(spentLabel).Contains(p))
                {
                    ValueMouseDown(UiMetrics.EquationFieldSpent);
                    return;
                }
                if (ValueRect(totalLabel).Contains(p))
                {
                    ValueMouseDown(UiMetrics.EquationFieldTotal);
                    return;
                }
            }

            if (p.Y <= UiMetrics.HeaderHeight)
            {
                DateTime now = DateTime.UtcNow;
                if ((now - lastHeaderClick).TotalMilliseconds > Timing.HeaderClickWindowMilliseconds)
                    headerClicks = 0;
                lastHeaderClick = now;
                headerClicks++;
                if (headerClicks >= UiMetrics.HeaderClickCount)
                {
                    headerClicks = 0;
                    OpenSettings();
                    return;
                }
            }

            ReleaseCapture();
            SendMessage(Handle, WM_NCLBUTTONDOWN, (IntPtr)HT_CAPTION, IntPtr.Zero);
        }

        private void ResizeMouseMove(object sender, MouseEventArgs e)
        {
            if (resizing)
            {
                int dx = Cursor.Position.X - resizeStartX;
                Rectangle b = resizeStartBounds;
                int frame = Width - ClientSize.Width;
                int minOuter = AppConfig.MinWindowWidth + frame;
                int maxOuter = AppConfig.MaxWindowWidth + frame;
                if (resizeEdge == UiMetrics.ResizeDirectionLeft)
                {
                    int newLeft = b.Left + dx;
                    int newWidth = b.Width - dx;
                    if (newWidth < minOuter) { newLeft = b.Right - minOuter; newWidth = minOuter; }
                    if (newWidth > maxOuter) { newLeft = b.Right - maxOuter; newWidth = maxOuter; }
                    Bounds = new Rectangle(newLeft, b.Top, newWidth, b.Height);
                }
                else
                {
                    int newWidth = b.Width + dx;
                    if (newWidth < minOuter) newWidth = minOuter;
                    if (newWidth > maxOuter) newWidth = maxOuter;
                    Bounds = new Rectangle(b.Left, b.Top, newWidth, b.Height);
                }
                return;
            }

            Point p = PointToClient(Cursor.Position);
            if (!cfg.WidthLocked && (p.X <= UiMetrics.ResizeLeftHotZone ||
                p.X >= ClientSize.Width - UiMetrics.ResizeRightHotZone)) Cursor = Cursors.SizeWE;
            else if (Cursor == Cursors.SizeWE) Cursor = Cursors.Default;
        }

        private void ResizeMouseUp(object sender, MouseEventArgs e)
        {
            if (!resizing) return;
            resizing = false;
            Capture = false;
            Cursor = Cursors.Default;
            resizeEdge = 0;
            cfg.WindowWidth = Math.Max(AppConfig.MinWindowWidth, Math.Min(AppConfig.MaxWindowWidth, ClientSize.Width));
            cfg.X = Left;
            cfg.Y = Top;
            cfg.Save();
        }

        protected override CreateParams CreateParams
        {
            get
            {
                CreateParams cp = base.CreateParams;
                cp.ExStyle |= WS_EX_TOOLWINDOW;
                return cp;
            }
        }

        protected override void WndProc(ref Message m)
        {
            if (m.Msg == WM_EXITSIZEMOVE)
            {
                int edge = DockEdge();
                if (cfg.EdgeHide && edge != EdgeMetrics.DockNone)
                {
                    dockedEdge = edge;
                    Location = VisibleLocation();
                    slideAnimating = false;
                    slideOutTarget = false;
                    slideTimer.Stop();
                    edgeHidden = false;
                    edgeArmed = true;
                    lastInside = DateTime.UtcNow;
                    hiddenHoverStart = DateTime.MinValue;
                    hideNotBefore = DateTime.MinValue;
                    edgeTimer.Start();
                }
                else
                {
                    dockedEdge = EdgeMetrics.DockNone;
                    edgeHidden = false;
                    slideAnimating = false;
                    slideOutTarget = false;
                    slideTimer.Stop();
                    edgeTimer.Stop();
                }
                cfg.X = Left;
                cfg.Y = Top;
                cfg.WindowWidth = Math.Max(AppConfig.MinWindowWidth, Math.Min(AppConfig.MaxWindowWidth, ClientSize.Width));
                SaveDockState();
                cfg.Save();
                SyncDisplayTiming();
                Invalidate();
            }
            if (m.Msg == WM_DISPLAYCHANGE)
            {
                SyncDisplayTiming();
            }
            if (m.Msg == WM_SETTINGCHANGE || m.Msg == WM_THEMECHANGED)
            {
                if (cfg.ThemeMode == AppConfig.ThemeFollowSystem)
                {
                    bool light = IsSystemLightTheme();
                    if (light != lightTheme) ApplyTheme(light);
                }
            }
            base.WndProc(ref m);
        }

        protected override void OnResize(EventArgs e)
        {
            base.OnResize(e);
            if (Width <= 0 || Height <= 0) return;
            LayoutContent();
            ApplyRoundedRegion();
            Invalidate();
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            base.OnPaint(e);
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (GraphicsPath p = Ui.Rounded(new Rectangle(0, 0,
                Width - UiMetrics.WindowBorderInset, Height - UiMetrics.WindowBorderInset),
                UiMetrics.WindowCornerRadius))
            using (Pen pen = new Pen(Palette.WindowBorder))
                g.DrawPath(pen, p);
            PaintEdgeHint(g);
        }

        protected override void OnLoad(EventArgs e)
        {
            base.OnLoad(e);
            if (placed) return;
            placed = true;
            Rectangle wa = Screen.PrimaryScreen.WorkingArea;
            int x = cfg.X;
            int y = cfg.Y;
            bool onScreen = false;
            foreach (Screen s in Screen.AllScreens)
            {
                Rectangle r = new Rectangle(x, y, Width, Height);
                if (s.WorkingArea.IntersectsWith(r)) { onScreen = true; break; }
            }
            if (x == AppConfig.UnsetCoordinate || y == AppConfig.UnsetCoordinate || !onScreen)
            {
                x = wa.Right - Width - UiMetrics.InitialWindowRightInset;
                y = wa.Top + UiMetrics.InitialWindowTop;
            }
            Location = new Point(x, y);
        }

        protected override void OnShown(EventArgs e)
        {
            base.OnShown(e);
            ApplyCaptureVisibility();
            SyncDisplayTiming();
            uiTimer.Start();
            barTimer.Start();
            if (demoMode) ApplyDemo();
            else StartFetch();

            bool startupDocked = false;
            if (cfg.EdgeHide && cfg.EdgeDock >= EdgeMetrics.DockLeft &&
                cfg.EdgeDock <= EdgeMetrics.DockBottom)
            {
                Rectangle wa = Screen.FromControl(this).WorkingArea;
                Location = EdgeLocation(cfg.EdgeDock, cfg.EdgeAnchor, wa);
                dockedEdge = cfg.EdgeDock;
                startupDocked = true;
            }
            else
            {
                dockedEdge = cfg.EdgeHide ? DockEdge() : EdgeMetrics.DockNone;
                if (dockedEdge != EdgeMetrics.DockNone)
                {
                    Location = VisibleLocation();
                    startupDocked = true;
                }
            }

            DateTime now = DateTime.UtcNow;
            edgeArmed = startupDocked;
            lastInside = now;
            hiddenHoverStart = DateTime.MinValue;
            hideNotBefore = startupDocked
                ? now.AddMilliseconds(Timing.StartupHideDelayMilliseconds)
                : DateTime.MinValue;
            if (startupDocked)
            {
                SaveDockState();
                cfg.Save();
            }
            SyncHighResolutionTimer();
            edgeTimer.Start();
            foreach (string arg in Environment.GetCommandLineArgs())
            {
                if (string.Equals(arg, "--settings", StringComparison.OrdinalIgnoreCase))
                {
                    BeginInvoke(new Action(OpenSettings));
                    break;
                }
            }
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            if (editingField != UiMetrics.EquationFieldNone) EndEdit(true);
            Point save = dockedEdge != EdgeMetrics.DockNone ? VisibleLocation() : Location;
            cfg.X = save.X;
            cfg.Y = save.Y;
            cfg.WindowWidth = Math.Max(AppConfig.MinWindowWidth, Math.Min(AppConfig.MaxWindowWidth, ClientSize.Width));
            cfg.TopMost = TopMost;
            cfg.Language = Strings.Code;
            SaveDockState();
            cfg.Save();
            uiTimer.Stop();
            barTimer.Stop();
            edgeTimer.Stop();
            slideTimer.Stop();
            SetHighResolutionTimer(false);
            tips.Dispose();
            base.OnFormClosing(e);
        }

        private void OpenSettings()
        {
            EnsureEdgeVisible();
            string oldDeepSeekKey = cfg.DeepSeekKey;
            string oldOpenCodeKey = cfg.OpenCodeKey;
            refreshingPaused = true;
            try
            {
                using (SettingsForm f = new SettingsForm(cfg))
                {
                    if (f.ShowDialog(this) == DialogResult.OK)
                    {
                        bool deepSeekChanged = cfg.DeepSeekKey != oldDeepSeekKey;
                        bool openCodeChanged = cfg.OpenCodeKey != oldOpenCodeKey;
                        if (deepSeekChanged)
                        {
                            InvalidateDeepSeekFetch();
                            deepSeekLastSuccess = null;
                            lastDeepSeekBalanceKnown = false;
                            deepSeekStatus.Text = Strings.Loading;
                            deepSeekStatus.ForeColor = Palette.Sub;
                            UpdateDisplay();
                        }
                        if (openCodeChanged)
                        {
                            InvalidateOpenCodeFetch();
                            openCodeLastSuccess = null;
                            ClearOpenCodeRows();
                        }
                        UpdateFetchTooltips();
                        lastDeepSeekFetchStamp = Timing.NoStamp;
                        lastOpenCodeFetchStamp = Timing.NoStamp;
                        StartFetch();
                    }
                }
            }
            finally { refreshingPaused = false; }
        }

        protected override void OnHandleCreated(EventArgs e)
        {
            base.OnHandleCreated(e);
            ApplyCaptureVisibility();
        }

        private void ApplyCaptureVisibility()
        {
            if (!IsHandleCreated) return;
            uint desired = WDA_NONE;
            if (cfg.HideFromCapture)
            {
                desired = Environment.OSVersion.Version.Build >= CaptureExcludeMinBuild
                    ? WDA_EXCLUDEFROMCAPTURE : WDA_MONITOR;
            }

            uint applied = desired;
            bool appliedOk = SetWindowDisplayAffinity(Handle, applied);
            if (!appliedOk && desired == WDA_EXCLUDEFROMCAPTURE)
            {
                applied = WDA_MONITOR;
                appliedOk = SetWindowDisplayAffinity(Handle, applied);
            }
            captureExcluded = appliedOk && applied != WDA_NONE;
            captureBlackedOut = appliedOk && applied == WDA_MONITOR;
        }

        private void SyncDisplayTiming()
        {
            if (!IsHandleCreated) return;
            Screen screen = Screen.FromControl(this);
            displayRefreshHz = DisplayTiming.HighestRefreshHz(screen);
            int interval = DisplayTiming.FrameIntervalMilliseconds(displayRefreshHz);
            if (barTimer == null || slideTimer == null) return;
            if (interval == frameIntervalMilliseconds) return;
            frameIntervalMilliseconds = interval;
            barTimer.Interval = interval;
            slideTimer.Interval = interval;
        }

        private void SetHighResolutionTimer(bool enabled)
        {
            if (enabled == highResolutionTimer) return;
            if (enabled)
                highResolutionTimer = DisplayTiming.BeginHighResolutionTimer();
            else
            {
                DisplayTiming.EndHighResolutionTimer();
                highResolutionTimer = false;
            }
        }

        private void SyncHighResolutionTimer()
        {
            SetHighResolutionTimer(!edgeHidden || slideAnimating || !cfg.EdgeHide);
        }
    }
}

